def permutation_coefficient(n, k):
    if k > n:
        return 0
    result = 1
    for i in range(n, n-k, -1):
        result *= i
    return result

def count_element_freq(tup):
    freq = {}
    for item in tup:
        if isinstance(item, tuple):
            for sub_item in item:
                if sub_item in freq:
                    freq[sub_item] += 1
                else:
                    freq[sub_item] = 1
        else:
            if item in freq:
                freq[item] += 1
            else:
                freq[item] = 1
    return freq
